<script setup lang="ts">
import ModalDialog from '../components/ModalDialog.vue';
import {confirmAction,promptAction} from '../lib/dialog';
import {orderCharacters} from '../lib/character-order';
import { ref,computed,onMounted,watch } from 'vue';import EventPicker from '../components/EventPicker.vue';import { api,catalog } from '../lib/api';import type { Character,CharacterList } from '../../shared/models';
const chars=ref<Character[]>([]),lists=ref<CharacterList[]>([]),query=ref(''),listId=ref(''),showHidden=ref(false),error=ref(''),busy=ref(false),newNames=ref(''),newList=ref(''),color=ref('#80636f'),editing=ref<Character|null>(null),editName=ref(''),editColor=ref(''),editFavorite=ref(false),editHidden=ref(false),editArchive=ref(false);
async function load(){if(!catalog.eventId)return;try{const s=await api<{characters:Character[];lists:CharacterList[]}>('/api/admin/events/'+catalog.eventId+'/characters');chars.value=orderCharacters(s.characters.filter(c=>c.id!=='aux-narrator'));lists.value=s.lists;}catch(e){error.value=(e as Error).message;}}watch(()=>catalog.eventId,load);onMounted(load);
const names=computed(()=>Array.from(new Set(newNames.value.split(/\n|，|,/).map(x=>x.trim()).filter(Boolean))));const filtered=computed(()=>chars.value.filter(c=>(showHidden.value||(!c.hidden&&!c.archived))&&(!listId.value||lists.value.find(l=>l.id===listId.value)?.members.includes(c.id))&&[c.name,c.japanese_name,...c.aliases??[],c.display_name??''].some(x=>x.toLowerCase().includes(query.value.toLowerCase()))).sort((a,b)=>listId.value?(lists.value.find(l=>l.id===listId.value)!.members.indexOf(a.id)-lists.value.find(l=>l.id===listId.value)!.members.indexOf(b.id)):Number(b.favorite??0)-Number(a.favorite??0)));
async function op(data:object){await api('/api/admin/events/'+catalog.eventId+'/characters/operations',{...data,operation_id:crypto.randomUUID()});}
async function add(){busy.value=true;try{for(const name of names.value){if(chars.value.some(c=>c.event_id===catalog.eventId&&c.name===name&&!c.archived))continue;await op({type:'character.add',id:crypto.randomUUID(),name,color:color.value,list_id:listId.value||null});await load();}newNames.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function addList(){try{await op({type:'list.add',id:crypto.randomUUID(),name:newList.value});newList.value='';await load();}catch(e){error.value=(e as Error).message;}}
function edit(c:Character){editing.value=c;editName.value=c.display_name??c.name;editColor.value=c.color;editFavorite.value=!!c.favorite;editHidden.value=!!c.hidden;editArchive.value=!!c.archived;}
async function save(){if(!editing.value)return;busy.value=true;try{const c=editing.value;if(c.kind==='custom')await op({type:'character.update',id:c.id,expectedVersion:c.version,name:editName.value,color:editColor.value,archived:editArchive.value});await op({type:'character.override',id:c.id,expectedVersion:c.override_version??0,color:editColor.value,display_name:c.kind==='custom'?null:editName.value===c.name?null:editName.value,hidden:editHidden.value,favorite:editFavorite.value});await load();editing.value=null;}catch(e){error.value=(e as Error).message;await load();}finally{busy.value=false;}}
async function membership(c:Character){const l=lists.value.find(x=>x.id===listId.value);if(!l)return;try{await op({type:'list.update',id:l.id,expectedVersion:l.version,name:l.name,archived:!!l.archived,position:l.position,members:l.members.includes(c.id)?l.members.filter(id=>id!==c.id):[...l.members,c.id]});await load();}catch(e){error.value=(e as Error).message;}}
async function moveMember(c:Character,offset:number){const l=lists.value.find(x=>x.id===listId.value);if(!l)return;const members=[...l.members],i=members.indexOf(c.id),j=i+offset;if(j<0||j>=members.length)return;[members[i],members[j]]=[members[j]!,members[i]!];try{await op({type:'list.update',id:l.id,expectedVersion:l.version,name:l.name,archived:!!l.archived,position:l.position,members});await load();}catch(e){error.value=(e as Error).message;}}
async function archiveList(){const l=lists.value.find(x=>x.id===listId.value);if(!l||!await confirmAction('归档此角色列表？角色及历史台词仍会保留。'))return;try{await op({type:'list.update',id:l.id,expectedVersion:l.version,name:l.name,archived:true,position:l.position,members:l.members});listId.value='';await load();}catch(e){error.value=(e as Error).message;}}
</script>
<template><div class="page"><header class="page-head"><div><h1>角色库</h1></div><EventPicker/></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><div class="filters paper"><label>查找角色<input v-model="query" type="search" placeholder="中文名 / 日文名 / 别名"></label><label>角色列表<select v-model="listId"><option value="">全部角色</option><option v-for="l in lists.filter(l=>!l.archived)" :value="l.id">{{ l.name }}</option></select></label><label class="check"><input type="checkbox" v-model="showHidden">显示隐藏或已归档</label><button v-if="listId" @click="archiveList">归档列表</button></div><div class="character-grid"><article v-for="c in filtered" :key="c.id" class="character-card" :style="{'--character-color':c.color}"><span class="character-symbol">{{ c.display_name?.slice(0,1)??c.name.slice(0,1) }}</span><div><h3>{{ c.display_name??c.name }} <span v-if="c.favorite">★</span></h3><small>{{ c.japanese_name||'活动自定义角色' }}</small><p class="hint">{{ c.aliases?.join(' · ') }}</p><small v-if="c.sources?.some(s=>s.verification==='supplementary-needs-primary-check')">补充条目 · 待官方资料核对</small><small v-if="c.hidden||c.archived">{{ c.archived?'已归档':'已隐藏' }}</small></div><div class="inline"><button @click="edit(c)">设置</button><button v-if="listId" aria-label="角色在列表内上移" @click="moveMember(c,-1)">↑</button><button v-if="listId" aria-label="角色在列表内下移" @click="moveMember(c,1)">↓</button><button v-if="listId" @click="membership(c)">从列表移除</button></div></article></div><p v-if="!filtered.length" class="empty">没有符合条件的角色。</p><div class="grid two"><section class="paper"><h2>批量添加活动角色</h2><label>名称（每行一个，自动去重）<textarea v-model="newNames" rows="4"></textarea></label><p class="hint">预览：{{ names.join('、')||'等待输入' }}</p><label>应援色<input v-model="color" type="color"></label><button class="primary" :disabled="busy||!names.length" @click="add">添加 {{ names.length }} 位角色{{ listId?'至当前列表':'' }}</button></section><section class="paper"><h2>建立角色列表</h2><form class="inline" @submit.prevent="addList"><input v-model="newList" required placeholder="例如：开场主持组" aria-label="新角色列表名称"><button>创建</button></form><p class="hint">选择列表后，下面可添加已有角色。</p><label v-if="listId">加入已有角色<select value="" @change="membership(chars.find(c=>c.id===($event.target as HTMLSelectElement).value)!);($event.target as HTMLSelectElement).value=''"><option value="">选择角色…</option><option v-for="c in chars.filter(c=>!c.archived&&!lists.find(l=>l.id===listId)?.members.includes(c.id))" :value="c.id">{{ c.display_name??c.name }}</option></select></label><a class="hint" href="https://gochiusa.com/chara/" target="_blank" rel="noopener noreferrer">官方角色资料 ↗</a></section></div><ModalDialog v-if="editing" :title="editing.name+' · 角色设置'" @close="editing=null"><form @submit.prevent="save"><label>{{ editing.kind==='custom'?'名称':'本活动显示名' }}<input v-model="editName" required></label><label>应援色<input v-model="editColor" type="color"></label><label class="check"><input v-model="editFavorite" type="checkbox">收藏</label><label class="check"><input v-model="editHidden" type="checkbox">从角色选择器隐藏</label><label v-if="editing.kind==='custom'" class="check"><input v-model="editArchive" type="checkbox">归档（保留历史台词）</label><div class="inline"><button type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存</button></div></form></ModalDialog></div></template>
